(N, M) = input().split()
(N, M) = (int(N), int(M))
A = list(map(int, input().split()))
B = list(map(int, input().split()))
low = 0
high = A[0] * B[0]
for day in range(1, N):
	high = max(high, A[day] * B[day])
while low < high:
	mid = (low + high) // 2
	bal = 0
	for day in range(N):
		if B[day] != 0:
			bal += max(A[day] - mid // B[day], 0)
	if bal <= M:
		high = mid
	else:
		low = mid + 1
print(low)
